mapper.select:
SELECT *
FROM lunaerp_production_yarn_type
WHERE id = #{id}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_production_yarn_type
SET deleted = 0,
    status = 'INACTIVE',
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_production_yarn_type
WHERE id = #{id}
  AND deleted = 1
  AND tenant_id = #{tenantId}
